    for request in requests.iterator(chunk_size=500):
        Registration.objects.using(alias).create(
            id=request.pk, company_id=request.company_id, asset_id=request.asset_id,
            result_issued_code_id=request.result_issued_code_id,
            idempotency_key=request.idempotency_key, request_hash=request.request_hash,
            source="legacy_finance", registered_by_id=request.created_by_id,
            registered_at=request.completed_at,
        )
    if Asset.objects.using(alias).filter(current_issued_code__isnull=False).exclude(
        pk__in=Registration.objects.using(alias).values("asset_id")
    ).exists():
        raise RuntimeError("发现缺少原财务建档历史的正式资产；请核查原数据，不会补造历史。")


