    if Asset.objects.using(alias).filter(asset_status="pending_finance").exclude(pk__in=photographed).exists():
        raise RuntimeError("存在无照片的旧流程待办，旧结构无法兼容；不能通过降级丢弃这些记录。")
    if schema_editor.connection.vendor == "postgresql":
        schema_editor.execute("""
            DROP TRIGGER IF EXISTS trg_asset_registration_commit ON assets_assetregistration;
            DROP TRIGGER IF EXISTS trg_asset_registration_guard ON assets_assetregistration;
            DROP FUNCTION IF EXISTS assets_guard_registration();
        """)
